u1=U("tenses","Narrative tenses and sequencing","B1",
 "Stories use three past tenses together: past simple for the main events, past continuous for the background, past perfect for something that happened earlier. Sequencing words guide the listener.",
 "গল্পে মূল ঘটনা past simple, পটভূমি past continuous, আর আগের ঘটনা past perfect। first, then, eventually দিয়ে ক্রম বোঝান।",
 [("Background","It was raining and I was waiting for a bus."),("Main event","Suddenly a rickshaw stopped and the driver called my name."),("Earlier event","I had left my phone in the office.")],
 [("Past continuous sets the scene; past simple interrupts it.","চলমান পটভূমি past continuous, হঠাৎ ঘটনা past simple।","I was presenting when the power went off."),
  ("Past perfect = earlier than another past event.","অতীতের আরও আগের ঘটনা past perfect।","When I arrived, the meeting had already started."),
  ("Sequence with first, then, after that, eventually.","ক্রম বোঝাতে first, then, after that, eventually।","First we got lost, then the car broke down, and eventually we arrived at midnight."),
  ("Just as = at exactly the same moment.","ঠিক সেই মুহূর্তে বোঝাতে just as।","Just as I was leaving, my boss called me back."),
  ("Eventually = in the end, after a long time; not 'possibly'.","eventually মানে শেষ পর্যন্ত, 'সম্ভবত' নয়।","Eventually, Rafi found a flat near his office.")],
 ["while","when","just as","eventually","by the time","after that"],
 [("When I reached, the bus already left.","When I got there, the bus had already left.","Earlier event needs past perfect; reach needs an object.","আগের ঘটনায় had + V3।"),
  ("I was knowing her since school.","I had known her since school.","Know is not used in continuous forms.","know সাধারণত continuous হয় না।"),
  ("Eventually it will rain, so take an umbrella.","It might rain, so take an umbrella.","Eventually means in the end, not possibly.","eventually মানে possibly নয়।")],
 [C("Background and interruption.","I ___ dinner when the guests arrived.",["was cooking","cooked","had cook","am cooking"],"was cooking","Background action."),
  T("An earlier past event.","By the time we got to the cinema, the film ___ started.","have",["had already","had"],"Past perfect."),
  C("Exact same moment.","___ I was locking the door, the phone rang.",["Just as","Eventually","After that","Firstly"],"Just as","Just as = at that moment."),
  F("Pick the correct sentence.",["While I walked to work, I was seeing an accident.","While I was walking to work, I saw an accident.","While I was walking to work, I was see an accident.","While I walk to work, I saw an accident."],"While I was walking to work, I saw an accident.","Continuous background + simple event."),
  B("শেষ পর্যন্ত আমরা রাত দুটোয় বাসায় পৌঁছালাম।",["Eventually, we got home at 2 am.","Eventually, we reached to home at 2 am.","Possibly we got home at 2 am.","At last time, we reached home 2 am."],"Eventually, we got home at 2 am.","Eventually = in the end."),
  C("Sequencing.","First we checked in, ___ we went straight to the beach.",["then","eventually","just as","while"],"then","Then = next."),
  T("Past continuous.","It ___ raining heavily, so we stayed inside.","be",["was"],"Background."),
  F("Pick the best sentence for a story.",["When I arrived, everyone had gone home.","When I arrived, everyone has gone home.","When I had arrived, everyone go home.","When I arrive, everyone had gone home."],"When I arrived, everyone had gone home.","Past simple + past perfect.",True),
  B("আমি অফিসে পৌঁছে বুঝলাম যে চাবি বাসায় ফেলে এসেছি।",["When I got to the office, I realised I had left my keys at home.","When I reached office, I realised I left my key in home.","When I got to the office, I was realising I have left my keys at home.","Reaching office, I realised I had forgot keys at home."],"When I got to the office, I realised I had left my keys at home.","Past perfect for the earlier action.",True)])
u2=U("listen","Reacting and remembering","B2",
 "Good listeners react: No way! Really? What happened next? Use used to and would to talk about past habits, especially in stories about childhood or old jobs.",
 "ভালো শ্রোতা প্রতিক্রিয়া দেখান: No way! Really? What happened next? অতীতের অভ্যাস বলতে used to আর would।",
 [("React","No way! · Really? · You're joking! · Oh no! · That's amazing!"),("Ask for more","What happened next? · So what did you do? · And then?"),("Past habits","I used to live in Rajshahi. · Every Eid we would visit my grandparents.")],
 [("Short reactions show interest.","ছোট প্রতিক্রিয়া আগ্রহ দেখায়।","\"I met Shakib Al Hasan at the airport!\" \"No way!\""),
  ("Ask questions to keep the story going.","প্রশ্ন করে গল্প এগিয়ে নিন।","So what did you do?"),
  ("Used to + verb: past habits and past states that are no longer true.","আগে ছিল, এখন নেই: used to + verb।","I used to hate coffee, but now I drink three cups a day."),
  ("Would + verb: repeated past actions, not states.","বারবার করা কাজের জন্য would; অবস্থার জন্য নয়।","In summer we would swim in the Padma every afternoon."),
  ("Negative and question: didn't use to / Did you use to…?","না-বাচক ও প্রশ্নে use to।","Did you use to play cricket at school?")],
 ["no way","really","what happened next","used to","would","you're joking"],
 [("I am used to go to school by bus.","I used to go to school by bus.","'Be used to' means be accustomed to.","be used to মানে অভ্যস্ত; অতীত অভ্যাসে used to।"),
  ("I would live in Rajshahi.","I used to live in Rajshahi.","Would is not used for states.","অবস্থা বোঝাতে would নয়।"),
  ("I didn't used to like tea.","I didn't use to like tea.","After didn't, use the base form.","didn't এর পরে use।")],
 [C("Your friend says she won a trip to Japan.","\"___ That's amazing!\"",["No way!","No, thanks.","Never mind.","Excuse me."],"No way!","Surprised reaction."),
  T("Past habit that stopped.","Rafi ___ to play football every evening in Rajshahi.","use",["used"],"Used to + base."),
  C("Keeping the story going.","\"Then the boss walked in.\" \"Oh no! What happened ___ ?\"",["next","after","then after","later on now"],"next","What happened next?"),
  F("Pick the correct sentence.",["When I was a child, I would have a dog.","When I was a child, I used to have a dog.","When I was a child, I was used to have a dog.","When I was a child, I use to had a dog."],"When I was a child, I used to have a dog.","States need used to, not would."),
  B("ছোটবেলায় প্রতি শুক্রবার আমরা নানুর বাড়ি যেতাম।",["When we were kids, we would visit our grandmother every Friday.","In childhood, we were going to grandmother's house every Friday.","When we were kids, we are used to visit our grandmother every Friday.","When we were kids, we would visited our grandmother every Friday."],"When we were kids, we would visit our grandmother every Friday.","Would for repeated actions."),
  T("Question about the past.","Did you ___ to live in Chattogram?","use",["use"],"Did you use to…?"),
  F("Pick the most natural listener reaction to bad news.",["Oh no! Are you OK?","Very bad.","It is sad news, I am informing.","OK, next."],"Oh no! Are you OK?","Sympathy + question."),
  C("Negative past habit.","I didn't ___ to enjoy reading, but now I love it.",["use","used","using","uses"],"use","Didn't use to.",True),
  B("সত্যি? তারপর তুমি কী করলে?",["Really? So what did you do?","Really? Then what you did?","True? After that what you do?","Really? So what you have done?"],"Really? So what did you do?","Question with did.",True)])
